import{c as l,$ as r,Q as o,j as s,g as e,o as i,n,m as d}from"./chunks/framework.Ce_49mA8.js";const h="/img/ru/front/workshop.webp",_=JSON.parse('{"title":"Оборудование и активы","description":"Универсальный учет оборудования, станков, приборов, инструментов и расчет их амортизации в ОмниКрафт ЕРП.","frontmatter":{"title":"Оборудование и активы","description":"Универсальный учет оборудования, станков, приборов, инструментов и расчет их амортизации в ОмниКрафт ЕРП.","datePublished":"2026-08-20","dateModified":"2026-11-14","order":1},"headers":[],"relativePath":"ru/docs/resources/assets.md","filePath":"ru/docs/resources/assets.md","lastUpdated":1794614400000}'),g={name:"ru/docs/resources/assets.md"},c={id:"оборудование-и-активы",tabindex:"-1"};function u(p,t,f,b,m,x){const a=r("DocIcon");return o(),s("div",null,[e("h1",c,[i(a,{name:"workshop"}),t[0]||(t[0]=n(" Оборудование и активы ",-1)),t[1]||(t[1]=e("a",{class:"header-anchor",href:"#оборудование-и-активы","aria-label":'Permalink to "Оборудование и активы"'},"​",-1))]),t[2]||(t[2]=d('<figure class="doc-image craft-window-frame" data-title="Оборудование и активы — ОмниКрафт ЕРП"><img src="'+h+'" alt="Главное окно вкладки «Мастерская» (Оборудование и активы)"><figcaption>Главное окно вкладки «Мастерская» (Оборудование и активы)</figcaption></figure><p>Вкладка <strong>«Мастерская»</strong> в программе служит единым центром управления долгосрочным имуществом вашего дела. Вне зависимости от направления — создаёте ли вы вещи вручную, управляете сервисным центром, развиваете магазин или продаёте товары на маркетплейсах — материальная база формирует фундамент вашего капитала.</p><p>Это не просто перечень станков и инструментов на полках. Раздел связывает физические предметы с управленческим балансом: показывает реальную текущую стоимость вашего бизнеса, автоматически начисляет износ и помогает закладывать амортизацию в расценки.</p><hr><h2 id="экономическии-смысл-перенос-ценности-в-баланс" tabindex="-1">Экономический смысл: Перенос ценности в баланс <a class="header-anchor" href="#экономическии-смысл-перенос-ценности-в-баланс" aria-label="Permalink to &quot;Экономический смысл: Перенос ценности в баланс&quot;">​</a></h2><p>В повседневной жизни покупку дорогого предмета часто воспринимают как денежную потерю. В профессиональном учете <strong>ОмниКрафт ЕРП</strong> приобретение средств производства работает по правилу сохранения капитала:</p><ol><li><strong>Капитал не уменьшается при покупке.</strong> Когда вы покупаете лазерный станок, паяльную станцию или термопринтер за 100 000 рублей, вы не теряете эти деньги. Вы меняете форму актива: свободные безналичные деньги из кассы превращаются в работающее оборудование. Общая ценность вашего бизнеса в отчете «Капитал» остаётся неизменной.</li><li><strong>Бережливый расчет износа.</strong> Промышленные бухгалтерские системы требуют высчитывать отработанные машино-часы по каждому агрегату. В ОмниКрафт ЕРП используется прямолинейный метод списания: <ul><li>Программа делит стоимость на срок службы и выводит <strong>точную сумму ежемесячного износа всей базы</strong>.</li><li>Зная эту сумму и объем выпуска или оказанных услуг, вы закладываете норматив износа в калькуляцию или накладные расходы. Оборудование планомерно окупает себя с каждого выполненного заказа.</li></ul></li></ol><div class="tip custom-block"><p class="custom-block-title">Линейная амортизация без формул</p><p>Если гравер куплен за 120 000 рублей на 5 лет (60 месяцев), программа ежемесячно уменьшает его остаточную стоимость на 2 000 рублей. В Капитале всегда отражается честная рыночная цена с учетом возраста станка, а не иллюзорная первоначальная сумма.</p></div><hr><h2 id="два-режима-учета-имущество-и-расходники" tabindex="-1">Два режима учета: Имущество и Расходники <a class="header-anchor" href="#два-режима-учета-имущество-и-расходники" aria-label="Permalink to &quot;Два режима учета: Имущество и Расходники&quot;">​</a></h2><p>В верхней части экрана расположен переключатель между двумя принципиально разными категориями материальных ресурсов:</p><table class="craft-matrix-table"><thead><tr><th style="width:50%;">Имущество (Основные средства)</th><th style="width:50%;">Расходники (Оснастка цеха)</th></tr></thead><tbody><tr><td><strong>Назначение:</strong> Долгосрочные основные средства (станки, верстаки, транспорт).</td><td><strong>Назначение:</strong> Быстроизнашиваемая рабочая оснастка (свёрла, фрезы, диски, кисти).</td></tr><tr><td><strong>Срок службы:</strong> От 1 года до десятков лет (задаётся в карточке).</td><td><strong>Срок службы:</strong> Не задаётся (короткий жизненный цикл).</td></tr><tr><td><strong>Влияние на баланс:</strong> Ежемесячная линейная амортизация в Капитал.</td><td><strong>Влияние на баланс:</strong> Прямой производственный расход в кассе (ДДС).</td></tr></tbody></table><h3 id="_1-долгосрочное-имущество" tabindex="-1">1. Долгосрочное имущество <a class="header-anchor" href="#_1-долгосрочное-имущество" aria-label="Permalink to &quot;1. Долгосрочное имущество&quot;">​</a></h3><p>Основные материальные средства, рассчитанные на долгий срок службы (станки, верстаки, приборы, оргтехника, мебель, автомобили).</p><ul><li>Для каждого объекта указывается <strong>срок службы</strong> в годах или месяцах.</li><li>Программа ежемесячно начисляет амортизацию, плавно снижая балансовую стоимость.</li><li>Остаточная стоимость объектов суммируется и формирует блок производственных активов в общем Капитале.</li></ul><h3 id="_2-расходники-и-рабочая-оснастка" tabindex="-1">2. Расходники и рабочая оснастка <a class="header-anchor" href="#_2-расходники-и-рабочая-оснастка" aria-label="Permalink to &quot;2. Расходники и рабочая оснастка&quot;">​</a></h3><p>Вспомогательные элементы и инструмент с коротким жизненным циклом (свёрла, фрезы, насадки, отрезные диски, кисти, технические жидкости).</p><ul><li>Для расходников <strong>не задается срок службы</strong> и не начисляется износ.</li><li>Их стоимость в полном объеме учитывается в расходах в журнале движения денег (ДДС) в момент приобретения.</li><li>Вы можете пополнять запас расходника кнопкой <strong>«Пополнить»</strong>, фиксируя новые партии без загромождения амортизационного списка.</li></ul><hr><h2 id="специфика-учета-по-направлениям" tabindex="-1">Специфика учета по направлениям <a class="header-anchor" href="#специфика-учета-по-направлениям" aria-label="Permalink to &quot;Специфика учета по направлениям&quot;">​</a></h2><p>Базовый механизм добавления и списания универсален, однако специфика зависит от характера вашей деятельности.</p><h3 id="services" tabindex="-1">В сфере услуг <a class="header-anchor" href="#services" aria-label="Permalink to &quot;В сфере услуг {#services}&quot;">​</a></h3><p>В сервисном центре, ремонтной мастерской, студии или салоне оборудование формирует рабочие посты мастеров:</p><ul><li><strong>Что вносить в Имущество:</strong> диагностические сканеры, паяльные комплексы, компрессоры, подъемники, стерилизаторы, профессиональные фены, кушетки, клиентскую мебель и компьютеры администратора.</li><li><strong>Что вносить в Расходники:</strong> защитные накладки, одноразовые насадки, припой, жала для паяльников, технические салфетки и смазки.</li><li><strong>Как окупать износ:</strong> общую сумму ежемесячной амортизации оборудования разделите на среднее количество заказ-нарядов в месяц и включите эту цифру в базовую стоимость нормо-часа или фиксированную наценку за операцию.</li></ul><h3 id="production" tabindex="-1">В производстве <a class="header-anchor" href="#production" aria-label="Permalink to &quot;В производстве {#production}&quot;">​</a></h3><p>В ремесленном или серийном цехе активы напрямую участвуют в преобразовании сырья в товар:</p><ul><li><strong>Что вносить в Имущество:</strong> раскройные столы, лазерные и фрезерные станки с числовым программным управлением, швейные машины, прессы для тиснения, печи для обжига и сушильные камеры.</li><li><strong>Что вносить в Расходники:</strong> сменные лезвия, швейные иглы, шлифовальные круги, зажимы и полировальные пасты.</li><li><strong>Как окупать износ:</strong> в модуле «Калькулятор» заложите норматив износа оборудования в технологическую карту изделия, чтобы себестоимость каждого выпущенного предмета резервировала фонд на обновление станков.</li></ul><h3 id="trade" tabindex="-1">В торговле и у селлеров маркетплейсов <a class="header-anchor" href="#trade" aria-label="Permalink to &quot;В торговле и у селлеров маркетплейсов {#trade}&quot;">​</a></h3><p>В ритейле и складской логистике оборудование обеспечивает упаковку, маркировку и товародвижение:</p><ul><li><strong>Что вносить в Имущество:</strong> термопринтеры для печати этикеток и штрихкодов, сканеры, запайщики пакетов, торговые витрины, стеллажные системы и электронные весы.</li><li><strong>Что вносить в Расходники:</strong> скотч, пузырьковую пленку, упаковочные пакеты и маркировочные ленты.</li><li><strong>Как окупать износ:</strong> амортизация складского оборудования включается в накладные коммерческие расходы на единицу отправления.</li></ul><hr><h2 id="работа-с-карточкои-актива-5-жизненных-сценариев" tabindex="-1">Работа с карточкой актива: 5 жизненных сценариев <a class="header-anchor" href="#работа-с-карточкои-актива-5-жизненных-сценариев" aria-label="Permalink to &quot;Работа с карточкой актива: 5 жизненных сценариев&quot;">​</a></h2><p>При нажатии кнопки <strong>«Добавить актив»</strong> открывается окно ввода параметров. Ниже разобраны ключевые жизненные ситуации, с которыми вы столкнетесь на практике:</p><h3 id="сценарии-1-первичныи-ввод-при-переходе-на-программу" tabindex="-1">Сценарий 1: Первичный ввод при переходе на программу <a class="header-anchor" href="#сценарии-1-первичныи-ввод-при-переходе-на-программу" aria-label="Permalink to &quot;Сценарий 1: Первичный ввод при переходе на программу&quot;">​</a></h3><p>Вам не нужно искать старые чеки пятилетней давности. Оцените станок по текущей рыночной цене подержанного аналога (на электронных досках объявлений) и укажите, сколько лет он ещё прослужит (например, 3 года). Программа начнет расчет износа с этой справедливой точки без искажения баланса.</p><h3 id="сценарии-2-безвозмездное-поступление-из-личного-гаража-или-по-гранту" tabindex="-1">Сценарий 2: Безвозмездное поступление (из личного гаража или по гранту) <a class="header-anchor" href="#сценарии-2-безвозмездное-поступление-из-личного-гаража-или-по-гранту" aria-label="Permalink to &quot;Сценарий 2: Безвозмездное поступление (из личного гаража или по гранту)&quot;">​</a></h3><p>Если вы принесли в мастерскую собственный инструмент, купленный до открытия дела, или получили оборудование по субсидии:</p><ul><li>В карточке укажите его оценочную стоимость.</li><li>В поле способа оплаты не привязывайте расход к кассе (ДДС).</li><li>Имущество появится на балансе и увеличит собственный капитал бизнеса, не создавая искусственной дыры в кассе.</li></ul><h3 id="сценарии-3-переоценка-из-за-инфляции" tabindex="-1">Сценарий 3: Переоценка из-за инфляции <a class="header-anchor" href="#сценарии-3-переоценка-из-за-инфляции" aria-label="Permalink to &quot;Сценарий 3: Переоценка из-за инфляции&quot;">​</a></h3><p>Если импортный станок из-за роста курса валют подорожал на вторичном рынке, нажмите кнопку <strong>«Переоценка»</strong> в меню строки:</p><ul><li>Укажите новую актуальную стоимость.</li><li>Программа пересчитает остаточную стоимость и ежемесячный износ.</li><li>Денежные счета не затронутся: изменится только оценка активов в управленческом балансе.</li></ul><h3 id="сценарии-4-текущее-обслуживание-против-модернизации" tabindex="-1">Сценарий 4: Текущее обслуживание против модернизации <a class="header-anchor" href="#сценарии-4-текущее-обслуживание-против-модернизации" aria-label="Permalink to &quot;Сценарий 4: Текущее обслуживание против модернизации&quot;">​</a></h3><p>Важно разделять два типа расходов на технику:</p><ul><li><strong>Текущий ремонт и ТО (замена масла, заточка, замена ремня):</strong> проводится как обычный расход в модуле движения денег (ДДС) со статьей «Обслуживание оборудования». Балансовая цена станка при этом не увеличивается.</li><li><strong>Капитальная модернизация (установка ЧПУ-контроллера, замена двигателя на мощный сервопривод):</strong> проведите трату в ДДС, а затем через редактирование карточки увеличьте стоимость станка на сумму доработки и продлите срок службы.</li></ul><h3 id="сценарии-5-списание-или-продажа" tabindex="-1">Сценарий 5: Списание или продажа <a class="header-anchor" href="#сценарии-5-списание-или-продажа" aria-label="Permalink to &quot;Сценарий 5: Списание или продажа&quot;">​</a></h3><ul><li><strong>При поломке без возможности восстановления:</strong> выберите пункт <strong>«Списать»</strong>. Актив переместится в архив списанных, а его остаточная стоимость уменьшит баланс бизнеса.</li><li><strong>При продаже:</strong> зафиксируйте выручку от продажи оборудования в кассе (ДДС) и отправьте карточку актива в архив.</li></ul><hr><h2 id="навигация-фильтры-и-порядок-в-реестре" tabindex="-1">Навигация, фильтры и порядок в реестре <a class="header-anchor" href="#навигация-фильтры-и-порядок-в-реестре" aria-label="Permalink to &quot;Навигация, фильтры и порядок в реестре&quot;">​</a></h2><p>Когда список имущества превышает несколько десятков позиций, используйте встроенные инструменты навигации верхней панели:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Инструмент</th><th style="text-align:left;">Назначение</th><th style="text-align:left;">Практическая польза</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Поиск по названию</strong></td><td style="text-align:left;">Мгновенная фильтрация по подстроке</td><td style="text-align:left;">Поиск инструмента по марке, инвентарному номеру или модели</td></tr><tr><td style="text-align:left;"><strong>Категории</strong></td><td style="text-align:left;">Группировка объектов по типам</td><td style="text-align:left;">Разделение на станки, приборы, электронику, мебель</td></tr><tr><td style="text-align:left;"><strong>Локации</strong></td><td style="text-align:left;">Фильтр по местам нахождения</td><td style="text-align:left;">Быстрый учет оборудования в основном цехе, на складе или в филиале</td></tr><tr><td style="text-align:left;"><strong>Сортировка колонок</strong></td><td style="text-align:left;">Сортировка по цене, дате ввода или износу</td><td style="text-align:left;">Контроль самых дорогих позиций или станков с истекающим сроком</td></tr><tr><td style="text-align:left;"><strong>Сброс фильтров</strong></td><td style="text-align:left;">Кнопка сброса параметров</td><td style="text-align:left;">Мгновенный возврат к полному списку всех активов</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Справочники категорий и мест хранения</p><p>Вы не ограничены предустановленными вариантами. По кнопке настроек справочников рядом с выпадающими списками можно создавать любые собственные категории (<em>«Лазерный участок»</em>, <em>«Пост пайки»</em>, <em>«Зона выдачи»</em>) под архитектуру вашего помещения.</p></div>',51))])}const k=l(g,[["render",u]]);export{_ as __pageData,k as default};
